// ============================================================================
// FUNCIONES AUXILIARES
// ============================================================================

inline float silu(float x) {
    return x / (1.0f + expf(-x));
}

inline float clamp(float x, float lo, float hi) {
    return x < lo ? lo : (x > hi ? hi : x);
}

// B-Splines cbicos
void compute_bsplines(float x, float* bases) {
    x = clamp(x, -2.5f, 2.5f);
    
    float b0[16], b1[15], b2[14];
    
    // Orden 0
    for (int j = 0; j < 16; j++) {
        b0[j] = (x >= GRID[j] && x < GRID[j+1]) ? 1.0f : 0.0f;
    }
    
    // Orden 1
    for (int j = 0; j < 15; j++) {
        float d1 = GRID[j+1] - GRID[j] + 1e-8f;
        float d2 = GRID[j+2] - GRID[j+1] + 1e-8f;
        b1[j] = (x - GRID[j]) / d1 * b0[j] + (GRID[j+2] - x) / d2 * b0[j+1];
    }
    
    // Orden 2
    for (int j = 0; j < 14; j++) {
        float d1 = GRID[j+2] - GRID[j] + 1e-8f;
        float d2 = GRID[j+3] - GRID[j+1] + 1e-8f;
        b2[j] = (x - GRID[j]) / d1 * b1[j] + (GRID[j+3] - x) / d2 * b1[j+1];
    }
    
    // Orden 3 (cbico)
    for (int j = 0; j < N_SPLINES; j++) {
        float d1 = GRID[j+3] - GRID[j] + 1e-8f;
        float d2 = GRID[j+4] - GRID[j+1] + 1e-8f;
        bases[j] = (x - GRID[j]) / d1 * b2[j] + (GRID[j+4] - x) / d2 * b2[j+1];
    }
}

// Capa KAN genrica
void kan_layer(const float* input, float* output,
               const float* base_w, const float* base_b,
               const float* spline_w,
               int in_dim, int out_dim) {
    
    float bases[N_SPLINES];
    
    for (int o = 0; o < out_dim; o++) {
        float sum = base_b[o];
        
        // Base lineal con SiLU
        for (int i = 0; i < in_dim; i++) {
            sum += base_w[o * in_dim + i] * silu(input[i]);
        }
        
        // Splines
        for (int i = 0; i < in_dim; i++) {
            compute_bsplines(input[i], bases);
            for (int s = 0; s < N_SPLINES; s++) {
                sum += spline_w[(o * in_dim + i) * N_SPLINES + s] * bases[s];
            }
        }
        
        output[o] = sum;
    }
}

// ============================================================================
// OBSERVADOR DE FLUJO SIMPLIFICADO
// ============================================================================
// Aproximacin: phi = integral(u - R*i) usando integrador discreto
class FluxObserver {
public:
    float phi_integrated;
    float phi_filtered;
    float alpha;  // Filtro paso bajo
    
public:
    FluxObserver() : phi_integrated(0.016f), phi_filtered(0.016f), alpha(0.1f) {}
    
    void reset(float phi_init = 0.016f) {
        phi_integrated = phi_init;
        phi_filtered = phi_init;
    }
    
    float update(float u, float i) {
        // Kirchhoff: u = R*i + dphi/dt  =>  dphi = (u - R*i) * dt
        float dphi = (u - R * i) * DT;
        phi_integrated += dphi;
        
        // Filtro paso bajo para estabilidad
        phi_filtered = alpha * phi_integrated + (1 - alpha) * phi_filtered;
        
        // Clamp a rango fsico [10mWb, 25mWb]
        phi_filtered = clamp(phi_filtered, 0.010f, 0.025f);
        
        return phi_filtered;
    }
};

// ============================================================================
// PREDICTOR DE POSICIN
// ============================================================================
float predict_position(float u, float i, float phi) {
    // 1. Normalizar entrada
    float input[3];
    input[0] = (u - U_MEAN) / U_STD;
    input[1] = (i - I_MEAN) / I_STD;
    input[2] = (phi - PHI_MEAN) / PHI_STD;
    
    // 2. Capa 1: [3] -> [32]
    float h1[32];
    kan_layer(input, h1, POS_KAN1_BASE_WEIGHT, POS_KAN1_BASE_BIAS, 
              POS_KAN1_SPLINE_W, 3, 32);
    
    // 3. Capa 2: [32] -> [16]
    float h2[16];
    kan_layer(h1, h2, POS_KAN2_BASE_WEIGHT, POS_KAN2_BASE_BIAS,
              POS_KAN2_SPLINE_W, 32, 16);
    
    // 4. Capa 3: [16] -> [1]
    float out[1];
    kan_layer(h2, out, POS_KAN3_BASE_WEIGHT, POS_KAN3_BASE_BIAS,
              POS_KAN3_SPLINE_W, 16, 1);
    
    // 5. Desnormalizar
    float y = out[0] * Y_STD + Y_MEAN;
    
    // 6. Clamp a rango fsico [2mm, 15mm]
    return clamp(y, 0.002f, 0.015f);
}

// ============================================================================
// PIPELINE COMPLETO
// ============================================================================
class SensorlessPipeline {
private:
    FluxObserver flux_obs;
    
public:
    SensorlessPipeline() {}
    
    void reset(float phi_init = 0.016f) {
        flux_obs.reset(phi_init);
    }
    
    // Estimacin completa de posicin desde (u, i)
    float estimate_position(float u, float i) {
        // Etapa 1: Estimar flujo
        float phi_est = flux_obs.update(u, i);
        
        // Etapa 2: Predecir posicin
        return predict_position(u, i, phi_est);
    }
    
    // Obtener flujo actual (para debug)
    float get_flux() const {
        return flux_obs.phi_filtered;
    }
};

